// op.ts
import { OpenPanel } from '@openpanel/sdk';

const clientSecret = process.env.PRIVYTICS_CLIENT_SECRET;

if (!clientSecret) {
  throw new Error('PRIVYTICS_CLIENT_SECRET is not set');
}

export const op = new OpenPanel({
  apiUrl: 'https://api.privytics.com',
  clientId: 'YOUR_CLIENT_ID',
  clientSecret,
});

import { op } from './op';

op.identify({
  profileId: '123', // Required
  firstName: 'Joe',
  lastName: 'Doe',
  email: 'joe@doe.com',
  properties: {
    tier: 'premium',
  },
});

import { op } from './op';

op.setGlobalProperties({
  app_version: '1.0.2',
  environment: 'production',
});
